#!/usr/bin/env node
/**
 * Coverage Tier Validation Script
 *
 * Reads coverage/coverage-summary.json (generated by vitest --coverage)
 * and validates per-tier coverage targets defined in
 * openspec/specs/wedding-trend/spec.md §7.1.
 *
 * Usage:
 *   node scripts/gates/check-coverage-tiers.mjs           # check generated report
 *   COVERAGE_JSON=path node scripts/gates/check-coverage-tiers.mjs  # custom path
 *
 * Exit codes:
 *   0 - All tiers pass
 *   1 - Some tiers below target
 *   2 - Coverage report not found
 *
 * このスクリプトが spec.md §7.1 に対する単一の真実（P2）。7段→3段への統合と
 * 未一致パターン検出の fail→warn 化は shared_plan/20 P3。未一致パターンの件数と
 * 一覧は coverage/stale-tier-patterns.json に書き出し、verify.mjs が実行終了時に
 * サマリ表示する（warn 化の必須付帯条件）。
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "../..");

const STALE_PATTERNS_OUT = resolve(ROOT, "coverage/stale-tier-patterns.json");

// ── Tier configuration (this file is the source of truth for spec.md §7.1) ──
// 7段→3段に統合（shared_plan/20 P3）。実質:
//   Tier 1（純粋ロジック 95%）: これ以上下げない。
//   Tier 2（パイプライン・スコア・LLM 制御・パース・公開ゲート 85%）
//   Tier 3（その他: 収集アダプタ・API ルート・データアクセス 70%）
//   除外（RSC / UI, smoke test で担保）
// 対象ファイルは実際の src/ ツリーに合わせて調整済み。
//
// 【暫定配置 / 要別計画（shared_plan/20 P3 判断 2026-09-01）】
//   src/lib/publish/gate.ts / invariants.ts / src/lib/sources/access-discipline.ts は
//   従来どの Tier にも属さず未計測だった。plan 20 では新規に Tier 2（85%）へ入れる
//   にとどめ、法務・公開ゲート系を Tier 1（95%）へ引き上げるのは新規テスト追加を
//   要するため別計画とする。llm/batch.ts も現状 77% のため Tier 3（70%）へ暫定配置。
const TIERS = [
  {
    name: "Tier 1: 純粋ロジック",
    target: 95,
    metric: "statements",
    patterns: [
      // 純粋ロジック。
      /\/lib\/url\.ts$/,
      /\/lib\/llm\/signature\.ts$/,
      /\/lib\/llm\/schemas\.ts$/,
      /\/lib\/constants\.ts$/,
      /\/lib\/scoring\/usefulness\.ts$/,
      // S9 で constants.ts から切り出したホスト allowlist。isAllowedArticleUrl は
      // articlePathPatterns による収集対象の強制そのものなので計測対象に含める。
      /\/lib\/sources\/host-allowlist\.ts$/,
    ],
  },
  {
    name: "Tier 2: パース・判定・公開ゲート・LLM 制御",
    target: 85,
    metric: "statements",
    patterns: [
      // 旧 Tier 2（パース・判定）。
      /\/lib\/sources\/base\/feed-parser\.ts$/,
      /\/lib\/embed\/providers\.ts$/,
      // 公開ゲート／法務不変条件の強制点（従来未計測。plan 20 P3 で新規計測）。
      /\/lib\/publish\/gate\.ts$/,
      /\/lib\/publish\/invariants\.ts$/,
      /\/lib\/sources\/access-discipline\.ts$/,
      // 旧 Tier 4（LLM 制御）のうち client.ts。batch.ts は現状 77% のため Tier 3 へ。
      /\/lib\/llm\/client\.ts$/,
    ],
  },
  {
    name: "Tier 3: 収集アダプタ・API ルート・データアクセス",
    target: 70,
    metric: "statements",
    patterns: [
      // 旧 Tier 4（LLM 制御）batch.ts。現状 77%。Tier 2 引き上げは別計画。
      /\/lib\/llm\/batch\.ts$/,
      // 旧 Tier 3（収集アダプタ）。
      /\/lib\/sources\/(hatena-bookmark|google-news|note|ameblo)\.ts$/,
      /\/lib\/sources\/base\/rss-fetcher\.ts$/,
      /\/lib\/embed\/oembed\.ts$/,
      // S2（shared_plan/17）でレーン別の候補供給を切り出したアダプタ群。
      /\/lib\/pipeline\/adapters\/.+\.ts$/,
      // 旧 Tier 5（API ルート）。
      /\/app\/api\/ingest\/route\.ts$/,
      /\/app\/api\/submit-url\/route\.ts$/,
      // ルートハンドラから切り出した本体。以前はルート側で計測されていた。
      /\/lib\/pipeline\/ingest\.ts$/,
      // S2（shared_plan/17）で3レーンを統合した共通コアと、その薄いラッパー。
      // 旧 submit-url.ts / evergreen.ts はここに吸収された。公開ゲートの強制が
      // このコアへ移ったため、tier から漏らすとカバレッジ強制が消える。
      /\/lib\/pipeline\/run-pipeline\.ts$/,
      /\/lib\/pipeline\/retry-runner\.ts$/,
      /\/lib\/pipeline\/submit-via-pipeline\.ts$/,
      /\/lib\/pipeline\/evergreen-via-pipeline\.ts$/,
      // 旧 Tier 6（データアクセス）。
      /\/lib\/db\/repository\.ts$/,
      /\/lib\/db\/query\.ts$/,
      /\/lib\/db\/feed\.ts$/,
      /\/lib\/db\/ingest\.ts$/,
      /\/lib\/db\/publication\.ts$/,
      /\/lib\/db\/discovery\.ts$/,
      /\/lib\/db\/gate-state\.ts$/,
    ],
  },
  {
    name: "除外: RSC / UI",
    target: null, // Excluded from unit test coverage (verified via smoke test)
    metric: "statements",
    patterns: [/\/app\/page\.tsx$/, /\/app\/layout\.tsx$/, /\/components\/.+\.tsx$/],
  },
];

// ── Helpers ────────────────────────────────────────────────────────────

function loadCoverage(path) {
  if (!existsSync(path)) {
    console.error(`[coverage-check] Coverage report not found: ${path}`);
    console.error(`[coverage-check] Run 'pnpm exec vitest run --coverage' first.`);
    process.exit(2);
  }
  return JSON.parse(readFileSync(path, "utf-8"));
}

function metricKey(metric) {
  return metric === "statements" ? "statements" : metric;
}

/** Compute aggregate coverage for a set of files (optionally excluding some). */
function aggregateCoverage(report, files, metric) {
  if (files.length === 0) return null;

  let totalCovered = 0;
  let total = 0;

  for (const file of files) {
    const data = report[file];
    if (!data) continue;
    const key = metricKey(metric);
    totalCovered += data[key]?.covered ?? 0;
    total += data[key]?.total ?? 0;
  }

  if (total === 0) return null;
  return { pct: (totalCovered / total) * 100, covered: totalCovered, total };
}

function formatPct(value) {
  return `${value.toFixed(2)}%`;
}

// ── Main ───────────────────────────────────────────────────────────────

function main() {
  const jsonPath = process.env.COVERAGE_JSON || resolve(ROOT, "coverage/coverage-summary.json");

  const report = loadCoverage(jsonPath);

  /** All source file paths from the report. */
  const allFiles = Object.keys(report).filter((f) => f.includes("/src/"));

  let allPass = true;
  const results = [];

  // 陳腐化したパターンの検出。tier 全体が0件のときしか警告しない実装だと、
  // 他に有効なパターンがある tier の中で1本だけ死んだパターンが残っても
  // 見逃される。実際 S2 でファイルを削除・改名した際にこれが起き、
  // 統合後のコア（run-pipeline.ts 等）が長らく計測対象から外れていた。
  const stalePatterns = [];
  for (const tier of TIERS) {
    for (const pattern of tier.patterns) {
      if (!allFiles.some((f) => pattern.test(f))) {
        stalePatterns.push({ tier: tier.name, pattern: String(pattern) });
      }
    }
  }
  // shared_plan/20 P3: 未一致パターンは fail させず warn に留める。ただし件数と
  // 一覧を coverage/stale-tier-patterns.json に書き出し、verify.mjs が実行終了時に
  // サマリ表示する（サマリ出力とセットでなければ warn 化してはならない、が計画の必須条件）。
  try {
    writeFileSync(
      STALE_PATTERNS_OUT,
      JSON.stringify({ count: stalePatterns.length, patterns: stalePatterns }, null, 2),
    );
  } catch {
    // coverage/ ディレクトリが無い等。verify.mjs 側は存在しなければ 0 件扱い。
  }
  if (stalePatterns.length > 0) {
    console.warn(
      `\n⚠️  どのファイルにも一致しない tier パターンがあります（${stalePatterns.length} 件）。\n`,
    );
    for (const { tier, pattern } of stalePatterns) {
      console.warn(`   ${tier}\n   パターン: ${pattern}\n`);
    }
    console.warn(
      "   → ファイルを削除・改名した場合は tier 定義も追随させてください（warn: CI はブロックしません）。\n",
    );
  }

  for (const tier of TIERS) {
    const matchedFiles = allFiles.filter((f) => tier.patterns.some((p) => p.test(f)));

    if (matchedFiles.length === 0) {
      results.push({ tier: tier.name, status: "⚠️  No files matched" });
      continue;
    }

    if (tier.target === null) {
      const agg = aggregateCoverage(report, matchedFiles, tier.metric);
      const pctStr = agg ? formatPct(agg.pct) : "N/A";
      results.push({
        tier: tier.name,
        stmts: pctStr,
        status: `ℹ️  (${matchedFiles.length} files, excluded — smoke test で担保)`,
        pass: true,
      });
      continue;
    }

    const agg = aggregateCoverage(report, matchedFiles, tier.metric);
    if (!agg) {
      results.push({
        tier: tier.name,
        stmts: "N/A",
        status: "⚠️  No coverage data",
      });
      continue;
    }

    const primaryPct = agg.pct;
    let pass = primaryPct >= tier.target;
    if (!pass) allPass = false;

    const detail = `(${agg.covered}/${agg.total} ${tier.metric})`;

    results.push({
      tier: tier.name,
      stmts: formatPct(primaryPct),
      target: `${tier.target}%`,
      status: pass ? "✅ PASS" : "❌ FAIL",
      pass,
      detail,
    });
  }

  // ── Output ────────────────────────────────────────────────────────────
  console.log("");
  console.log("📊 Coverage Tier Validation");
  console.log("=".repeat(60));

  for (const r of results) {
    const line = [
      r.tier.padEnd(35),
      (r.stmts || "").padStart(8),
      r.target ? `  target: ${r.target}`.padEnd(12) : " ".padEnd(12),
      r.status || "",
      r.detail || "",
    ].join("");
    console.log(line);
  }

  console.log("=".repeat(60));

  if (allPass) {
    console.log("✅ All tiers meet coverage targets.\n");
    process.exit(0);
  } else {
    console.log("❌ Some tiers are below coverage targets.\n");
    process.exit(1);
  }
}

main();
